// BE_PDFPageCount counts the pages of a PDF in a container. The PDFs are generated by the writer; no sample file is used.
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { pdf, appendPdf } from '../../scripts/src/pdf.ts';
import { evaluateText } from '../../calc/src/index.ts';

const page = { width: 200, height: 200, ops: [] };
const count = (data: Uint8Array | undefined, expr = 'BE_PDFPageCount ( f ) & "/" & BE_GetLastError') =>
  evaluateText(expr, { field: (r) => (r.field === 'f' && data ? ({ type: 'container', value: 'a.pdf', data } as never) : undefined) });

test('BE_PDFPageCount counts pages, including pages added to an existing file', () => {
  const three = pdf([page, page, page]);
  assert.equal(count(three), '3/0');
  assert.equal(count(Buffer.concat([three, appendPdf(three, [page, page])])), '5/0');
});

test('BE_PDFPageCount gives ? for something that is not a readable PDF', () => {
  assert.equal(count(Buffer.from('not a pdf')), '?/-1');
  assert.equal(count(Buffer.from('%PDF-1.4\nnonsense')), '?/-1');
  assert.equal(count(undefined, 'BE_PDFPageCount ( "text" ) & "/" & BE_GetLastError'), '?/-1');
});
